export class HierarchicalPubSub {
  constructor() {
    this.subscribers = new Map();
  }

  subscribe(event, callback, priority = 1) {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event).push({ callback, priority });
    this.subscribers.get(event).sort((a, b) => b.priority - a.priority);
  }

  publish(event, data) {
    if (this.subscribers.has(event)) {
      for (const subscriber of this.subscribers.get(event)) {
        subscriber.callback(data);
      }
    }
  }

  allocateResources(event, computeUnits) {
    // Dynamically allocate compute based on event priority
    console.log(`Allocating ${computeUnits} units for event: ${event}`);
  }
}